import{a as e,n as t,o as n,r,s as i}from"./app-DuzyQjgf.js";import{t as a}from"./plugin-vue_export-helper-BDNMzG2s.js";var o=JSON.parse(`{"path":"/web3/smart/eth/","title":"Ethereum(ETH)","lang":"zh-CN","frontmatter":{"description":"Ethereum(ETH) 以太坊（Ethereum）由 Vitalik Buterin 于 2013 年首次提出，并在 2015 年 7 月 30 日正式推出。其主要创新在于引入了智能合约和以太坊虚拟机（EVM），使得开发者能够在区块链上创建和部署去中心化应用（dApps）。以太坊经历了多个重要的硬分叉，如 Homestead、Metropolis（...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Ethereum(ETH)\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-03-11T05:49:26.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"DeeLMind\\",\\"url\\":\\"https://deelmind.com\\"}]}"],["meta",{"property":"og:url","content":"https://deelmind.com/web3/smart/eth/"}],["meta",{"property":"og:site_name","content":"極客方舟"}],["meta",{"property":"og:title","content":"Ethereum(ETH)"}],["meta",{"property":"og:description","content":"Ethereum(ETH) 以太坊（Ethereum）由 Vitalik Buterin 于 2013 年首次提出，并在 2015 年 7 月 30 日正式推出。其主要创新在于引入了智能合约和以太坊虚拟机（EVM），使得开发者能够在区块链上创建和部署去中心化应用（dApps）。以太坊经历了多个重要的硬分叉，如 Homestead、Metropolis（..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-03-11T05:49:26.000Z"}],["meta",{"property":"article:modified_time","content":"2026-03-11T05:49:26.000Z"}]]},"git":{"createdTime":1734955114000,"updatedTime":1773208166000,"contributors":[{"name":"DeeLMind","username":"DeeLMind","email":"deelmind@gmail.com","commits":2,"url":"https://github.com/DeeLMind"}]},"readingTime":{"minutes":1.66,"words":498},"filePathRelative":"web3/smart/eth/README.md","autoDesc":true}`),s={name:`README.md`};function c(a,o,s,c,l,u){let d=i(`DocsAD`);return n(),t(`div`,null,[o[0]||=r(`<h1 id="ethereum-eth" tabindex="-1"><a class="header-anchor" href="#ethereum-eth"><span>Ethereum(ETH)</span></a></h1><p><a href="https://ethereum.org/en/developers/docs/" target="_blank" rel="noopener noreferrer">以太坊（Ethereum）</a>由 Vitalik Buterin 于 2013 年首次提出，并在 2015 年 7 月 30 日正式推出。其主要创新在于引入了智能合约和以太坊虚拟机（EVM），使得开发者能够在区块链上创建和部署去中心化应用（dApps）。以太坊经历了多个重要的硬分叉，如 Homestead、Metropolis（包括 Byzantium 和 Constantinople）和 Istanbul 等。每个分叉都带来了性能改进、安全性增强和新功能，以适应不断增长的用户需求和技术进步。</p><h2 id="_1-2013-年" tabindex="-1"><a class="header-anchor" href="#_1-2013-年"><span>1. 2013 年</span></a></h2><ul><li><strong>Vitalik Buterin 提出以太坊白皮书</strong>：以太坊的创始人 Vitalik Buterin 提出了以太坊的概念，旨在创建一个更为灵活的区块链平台，支持智能合约和去中心化应用。</li></ul><h2 id="_2-2014-年" tabindex="-1"><a class="header-anchor" href="#_2-2014-年"><span>2. 2014 年</span></a></h2><ul><li><strong>以太坊通过众筹筹集资金</strong>：以太坊进行了众筹，成功筹集了超过 1800 万美元，为项目的开发和启动提供了资金支持。</li></ul><h2 id="_3-2015-年" tabindex="-1"><a class="header-anchor" href="#_3-2015-年"><span>3. 2015 年</span></a></h2><ul><li><strong>以太坊网络正式上线</strong>：以太坊主网在 2015 年 7 月 30 日正式启动，标志着其从开发阶段转向实际运营。</li></ul><h2 id="_4-2016-年" tabindex="-1"><a class="header-anchor" href="#_4-2016-年"><span>4. 2016 年</span></a></h2><ul><li><strong>The DAO 攻击导致硬分叉</strong>：The DAO 是一个基于以太坊的去中心化投资基金，2016 年 6 月遭遇了攻击，导致大量以太币被盗。为了解决这一问题，以太坊社区决定进行硬分叉，结果产生了两个链：以太坊（ETH）和以太坊经典（ETC）。</li></ul><h2 id="_5-2017-年-2019-年" tabindex="-1"><a class="header-anchor" href="#_5-2017-年-2019-年"><span>5. 2017 年-2019 年</span></a></h2><ul><li><strong>多次硬分叉（Byzantium、Constantinople、Istanbul）</strong>：以太坊进行了多次硬分叉，分别是 Byzantium、Constantinople 和 Istanbul。这些升级引入了性能和安全改进，提高了网络的效率和稳定性。</li></ul><h2 id="_6-2020-年" tabindex="-1"><a class="header-anchor" href="#_6-2020-年"><span>6. 2020 年</span></a></h2><ul><li><strong>以太坊 2.0 启动</strong>：以太坊 2.0 正式启动，标志着以太坊向权益证明（PoS）机制的转型开始。这个版本的升级旨在提高以太坊网络的可扩展性和安全性。</li></ul>`,14),e(d)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};